module SafeCaller
  def self.call(callable, *args, default: nil)
    if callable.lambda? && !arity_matches?(callable, args.length)
      return default
    end
    callable.call(*args)
  end

  def self.arity_matches?(callable, count)
    params = callable.parameters
    return true if params.any? { |type, _| type == :rest }

    required = params.count { |type, _| type == :req }
    total = params.count { |type, _| [:req, :opt].include?(type) }

    count >= required && count <= total
  end
end
